49	  async function assertProjectEnvironmentSelection(companyId: string, environmentId: string | null | undefined) {
50	    if (environmentId === undefined || environmentId === null) return;
51	    await assertEnvironmentSelectionForCompany(environmentsSvc, companyId, environmentId, {
52	      allowedDrivers: ["local", "ssh", "sandbox"],
53	    });
54	  }
55	
56	  function readProjectPolicyEnvironmentId(policy: unknown): string | null | undefined {
57	    if (!policy || typeof policy !== "object" || !("environmentId" in policy)) {
58	      return undefined;
59	    }
60	    const environmentId = (policy as { environmentId?: unknown }).environmentId;
61	    return typeof environmentId === "string" || environmentId === null ? environmentId : undefined;
62	  }
63	
64	  async function resolveCompanyIdForProjectReference(req: Request) {
65	    const companyIdQuery = req.query.companyId;
66	    const requestedCompanyId =
67	      typeof companyIdQuery === "string" && companyIdQuery.trim().length > 0
68	        ? companyIdQuery.trim()
69	        : null;
70	    if (requestedCompanyId) {
71	      assertCompanyAccess(req, requestedCompanyId);
72	      return requestedCompanyId;
73	    }
74	    if (req.actor.type === "agent" && req.actor.companyId) {
75	      return req.actor.companyId;
76	    }
77	    return null;
78	  }
79	
80	  async function normalizeProjectReference(req: Request, rawId: string) {
81	    if (isUuidLike(rawId)) return rawId;
82	    const companyId = await resolveCompanyIdForProjectReference(req);
83	    if (!companyId) return rawId;
84	    const resolved = await svc.resolveByReference(companyId, rawId);
85	    if (resolved.ambiguous) {
86	      throw conflict("Project shortname is ambiguous in this company. Use the project ID.");
87	    }
88	    return resolved.project?.id ?? rawId;
89	  }
