118	  router.post("/companies/:companyId/projects", validate(createProjectSchema), async (req, res) => {
119	    const companyId = req.params.companyId as string;
120	    assertCompanyAccess(req, companyId);
121	    type CreateProjectPayload = Parameters<typeof svc.create>[1] & {
122	      workspace?: Parameters<typeof svc.createWorkspace>[1];
123	    };
124	
125	    const { workspace, ...projectData } = req.body as CreateProjectPayload;
126	    await assertProjectEnvironmentSelection(
127	      companyId,
128	      readProjectPolicyEnvironmentId(projectData.executionWorkspacePolicy),
129	    );
130	    assertNoAgentHostWorkspaceCommandMutation(
131	      req,
132	      [
133	        ...collectProjectExecutionWorkspaceCommandPaths(projectData.executionWorkspacePolicy),
134	        ...collectProjectWorkspaceCommandPaths(workspace, "workspace"),
135	      ],
136	    );
137	    if (projectData.env !== undefined) {
138	      projectData.env = await secretsSvc.normalizeEnvBindingsForPersistence(
139	        companyId,
140	        projectData.env,
141	        { strictMode: strictSecretsMode, fieldPath: "env" },
142	      );
143	    }
144	    const project = await svc.create(companyId, projectData);
145	    let createdWorkspaceId: string | null = null;
146	    if (workspace) {
147	      const createdWorkspace = await svc.createWorkspace(project.id, workspace);
148	      if (!createdWorkspace) {
149	        await svc.remove(project.id);
150	        res.status(422).json({ error: "Invalid project workspace payload" });
151	        return;
152	      }
153	      createdWorkspaceId = createdWorkspace.id;
154	    }
155	    const hydratedProject = workspace ? await svc.getById(project.id) : project;
156	
157	    const actor = getActorInfo(req);
158	    await logActivity(db, {
159	      companyId,
160	      actorType: actor.actorType,
161	      actorId: actor.actorId,
162	      agentId: actor.agentId,
163	      action: "project.created",
164	      entityType: "project",
165	      entityId: project.id,
166	      details: {
167	        name: project.name,
168	        workspaceId: createdWorkspaceId,
169	        envKeys: project.env ? Object.keys(project.env).sort() : [],
170	      },
171	    });
172	    const telemetryClient = getTelemetryClient();
173	    if (telemetryClient) {
174	      trackProjectCreated(telemetryClient);
175	    }
176	    res.status(201).json(hydratedProject ?? project);
177	  });
