179	  router.patch("/projects/:id", validate(updateProjectSchema), async (req, res) => {
180	    const id = req.params.id as string;
181	    const existing = await svc.getById(id);
182	    if (!existing) {
183	      res.status(404).json({ error: "Project not found" });
184	      return;
185	    }
186	    assertCompanyAccess(req, existing.companyId);
187	    const body = { ...req.body };
188	    assertNoAgentHostWorkspaceCommandMutation(
189	      req,
190	      collectProjectExecutionWorkspaceCommandPaths(body.executionWorkspacePolicy),
