196	    if (typeof body.archivedAt === "string") {
197	      body.archivedAt = new Date(body.archivedAt);
198	    }
199	    if (body.env !== undefined) {
200	      body.env = await secretsSvc.normalizeEnvBindingsForPersistence(existing.companyId, body.env, {
201	        strictMode: strictSecretsMode,
202	        fieldPath: "env",
203	      });
204	    }
205	    const project = await svc.update(id, body);
206	    if (!project) {
207	      res.status(404).json({ error: "Project not found" });
208	      return;
209	    }
210	
211	    const actor = getActorInfo(req);
212	    await logActivity(db, {
213	      companyId: project.companyId,
214	      actorType: actor.actorType,
215	      actorId: actor.actorId,
216	      agentId: actor.agentId,
217	      action: "project.updated",
218	      entityType: "project",
219	      entityId: project.id,
220	      details: {
221	        changedKeys: Object.keys(req.body).sort(),
222	        envKeys:
223	          body.env && typeof body.env === "object" && !Array.isArray(body.env)
224	            ? Object.keys(body.env as Record<string, unknown>).sort()
225	            : undefined,
226	      },
227	    });
228	
229	    res.json(project);
