606	  router.delete("/projects/:id/workspaces/:workspaceId", async (req, res) => {
607	    const id = req.params.id as string;
608	    const workspaceId = req.params.workspaceId as string;
609	    const existing = await svc.getById(id);
610	    if (!existing) {
611	      res.status(404).json({ error: "Project not found" });
612	      return;
613	    }
614	    assertCompanyAccess(req, existing.companyId);
